"use client";

import Image from "next/image";
import { useEffect, useMemo, useState } from "react";
import { AnimatePresence, motion, useReducedMotion, useScroll, useSpring } from "framer-motion";
import { ArrowDownRight, ArrowUpRight, ChevronRight, Menu, X } from "lucide-react";
import { MinimalistHero } from "@/components/ui/minimalist-hero";
import { archiveStats, chapters, formatData } from "@/data/archive";

const nav = ["Home", "Journey", "Stats", "Centuries", "Analytics", "Gallery", "Ask KLR"];

function Navigation() {
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState("home");
  useEffect(() => {
    const sections = nav.map(n => document.getElementById(n.toLowerCase().replace(" ", "-"))).filter(Boolean) as HTMLElement[];
    const observer = new IntersectionObserver(e => e.forEach(x => x.isIntersecting && setActive(x.target.id)), { rootMargin: "-45% 0px -45%" });
    sections.forEach(s => observer.observe(s)); return () => observer.disconnect();
  }, []);
  return <>
    <header className="nav-shell"><a className="wordmark" href="#home">KLR<span>01</span></a><nav className="desktop-nav" aria-label="Primary navigation">{nav.map(n => <a className={active === n.toLowerCase().replace(" ", "-") ? "active" : ""} href={`#${n.toLowerCase().replace(" ", "-")}`} key={n}>{n}</a>)}</nav><button className="menu-button" onClick={() => setOpen(v => !v)} aria-label={open ? "Close menu" : "Open menu"}>{open ? <X /> : <Menu />}</button></header>
    <AnimatePresence>{open && <motion.nav className="mobile-nav" initial={{ opacity: 0, clipPath: "inset(0 0 100% 0)" }} animate={{ opacity: 1, clipPath: "inset(0)" }} exit={{ opacity: 0, clipPath: "inset(0 0 100% 0)" }} aria-label="Mobile navigation">{nav.map((n,i) => <motion.a initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: i*.04 }} onClick={() => setOpen(false)} href={`#${n.toLowerCase().replace(" ", "-")}`} key={n}><span>0{i+1}</span>{n}</motion.a>)}</motion.nav>}</AnimatePresence>
  </>;
}

function Journey() {
  return <section id="journey" className="journey"><div className="section-intro"><p>01 / The journey</p><h2>A CAREER<br /><i>IN MOTION</i></h2><span>Scroll through the roles, resets and reinventions that shaped a modern Indian batter.</span></div>
    <div className="chapter-list">{chapters.map((c, i) => <article className="chapter" key={c.year}><div className="chapter-year">{c.year}</div><motion.div className="chapter-image" initial={{ opacity: .25, scale: .94 }} whileInView={{ opacity: 1, scale: 1 }} viewport={{ amount: .45 }} transition={{ duration: .8 }}><Image src={c.image} alt={`KL Rahul — ${c.kicker}`} fill sizes="(max-width: 768px) 90vw, 45vw" /></motion.div><div className="chapter-copy"><p>{c.kicker}</p><h3>{c.title}</h3><span>{c.body}</span><b>{c.stat}</b></div><div className="chapter-index">0{i+1}</div></article>)}</div>
  </section>;
}

function StatsLab() {
  const [format, setFormat] = useState<keyof typeof formatData>("Test");
  const points = useMemo(() => formatData[format].map((v,i,a) => `${(i/(a.length-1))*100},${100-v}`).join(" "), [format]);
  return <section id="stats" className="stats-section"><div className="stats-head"><p>02 / Career numbers</p><h2>NUMBERS<br />DON’T <i>LIE.</i></h2></div><div className="stat-strip">{archiveStats.map(s => <div key={s.label}><strong>{s.value}</strong><span>{s.label}</span></div>)}</div><div id="analytics" className="lab"><div className="lab-title"><span>Interactive form study</span><h3>THE PULSE</h3><p>Illustrative interface prototype. Connect a verified innings dataset to replace this normalized demonstration series.</p></div><div className="format-tabs" role="tablist" aria-label="Format">{Object.keys(formatData).map(f => <button role="tab" aria-selected={format===f} onClick={() => setFormat(f as keyof typeof formatData)} key={f}>{f}</button>)}</div><div className="chart-wrap"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-label={`${format} illustrative performance trend`}><defs><linearGradient id="gold" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#c9a96e" stopOpacity=".5"/><stop offset="1" stopColor="#c9a96e" stopOpacity="0"/></linearGradient></defs><polygon points={`0,100 ${points} 100,100`} fill="url(#gold)"/><polyline points={points} fill="none" stroke="#d8bd89" strokeWidth="1.2" vectorEffect="non-scaling-stroke"/></svg><div className="chart-labels"><span>EARLIER</span><b>{format.toUpperCase()}</b><span>RECENT</span></div></div></div></section>;
}

const centuries = [
  { score: "199", label: "The long-form peak", format: "TEST", image: "/images/rahul/journey/test-batter.jpg" },
  { score: "129", label: "An overseas statement", format: "TEST", image: "/images/rahul/journey/test-era-collage.jpg" },
  { score: "112", label: "White-ball control", format: "ODI", image: "/images/rahul/gallery/world-cup.webp" }
];
function CenturyVault() { const [selected,setSelected] = useState(0); return <section id="centuries" className="vault"><div className="vault-title"><p>03 / Selected innings</p><h2>CENTURY<br /><i>VAULT</i></h2></div><div className="vault-stage"><AnimatePresence mode="wait"><motion.div key={selected} className="vault-image" initial={{ opacity:0, scale:1.06 }} animate={{ opacity:1, scale:1 }} exit={{ opacity:0 }}><Image src={centuries[selected].image} alt={`KL Rahul — ${centuries[selected].label}`} fill sizes="65vw"/></motion.div></AnimatePresence><div className="vault-score"><span>{centuries[selected].format}</span><strong>{centuries[selected].score}</strong><p>{centuries[selected].label}</p></div></div><div className="vault-list">{centuries.map((c,i)=><button className={selected===i?"selected":""} onClick={()=>setSelected(i)} key={c.score}><span>0{i+1}</span><b>{c.score}</b><em>{c.label}</em><ChevronRight/></button>)}</div><p className="data-note">Selected verified score landmarks. Full match context and sourced innings data will be added through the documented data pipeline.</p></section> }

function Gallery() { const images=["/images/rahul/gallery/celebration.webp","/images/rahul/gallery/ipl-batting.webp","/images/rahul/hero/rahul-studio-portrait.jpg","/images/rahul/gallery/world-cup.webp","/images/rahul/gallery/resilience.jpg"]; return <section id="gallery" className="gallery"><div className="gallery-head"><p>04 / Photo story</p><h2>FRAME<br />BY <i>FRAME</i></h2></div><div className="filmstrip">{images.map((src,i)=><figure key={src} className={`frame frame-${i+1}`}><Image src={src} alt={`KL Rahul archive frame ${i+1}`} fill sizes="(max-width: 768px) 80vw, 30vw"/><figcaption><span>0{i+1}</span>{["Release","The IPL years","Stillness","India blue","Resilience"][i]}</figcaption></figure>)}</div></section> }

function Predictor() { const [value,setValue]=useState(50); return <section id="ask-klr" className="predict"><div><p>05 / Future lab</p><h2>PREDICT<br />THE NEXT<br /><i>INNINGS</i></h2></div><div className="predict-panel"><span>MODEL STATUS / DATA REQUIRED</span><h3>{value}</h3><p>Recent-form weighting</p><input aria-label="Recent-form weighting" type="range" min="0" max="100" value={value} onChange={e=>setValue(Number(e.target.value))}/><div className="predict-grid"><label>FORMAT<select><option>Test</option><option>ODI</option><option>T20</option></select></label><label>ROLE<select><option>Top order</option><option>Middle order</option><option>Wicketkeeper</option></select></label></div><button disabled>Awaiting trained model <ArrowUpRight/></button><small>No random output is generated. This interface unlocks only when a validated model artifact and API are connected.</small></div></section> }

function Finale() { return <section className="finale"><div className="then-now"><div><span>THEN</span><Image src="/images/rahul/journey/rahul-early.webp" alt="A young KL Rahul" fill sizes="40vw"/></div><ArrowDownRight/><div><span>NOW</span><Image src="/images/rahul/journey/india-current.jpg" alt="KL Rahul in the current era" fill sizes="40vw"/></div></div><h2>THE GAME CHANGED.<br /><i>SO DID HE.</i></h2><div className="final-screen"><span>KLR01</span><h2>THE<br />STORY<br /><i>CONTINUES.</i></h2></div></section> }

export function ArchiveExperience() {
  const { scrollYProgress } = useScroll(); const scaleX = useSpring(scrollYProgress,{ stiffness:120,damping:28,mass:.3 });
  const [loaded,setLoaded]=useState(false); const reduce=useReducedMotion(); useEffect(()=>{const t=setTimeout(()=>setLoaded(true), reduce?0:1100);return()=>clearTimeout(t)},[reduce]);
  return <><AnimatePresence>{!loaded && <motion.div className="loader" exit={{ y:"-100%" }} transition={{ duration:.7,ease:[.76,0,.24,1] }}><span>KLR01</span><div><motion.i initial={{scaleX:0}} animate={{scaleX:1}} transition={{duration:.8}}/></div><small>THE RAHUL ARCHIVE</small></motion.div>}</AnimatePresence><motion.div className="progress" style={{scaleX}}/><Navigation/><main><MinimalistHero/><Journey/><StatsLab/><CenturyVault/><Gallery/><Predictor/><Finale/></main><footer><div><b>KLR01</b><span>THE RAHUL ARCHIVE</span></div><p>An independent fan-made interactive tribute. Not affiliated with KL Rahul, BCCI, IPL, or any franchise.</p><a href="#home">BACK TO TOP ↑</a></footer></>;
}
